+        const data = await fetchEvaluation(trimmed, [], 'infix');
+        setResult(data.result);
+        setState('preview');
+      } catch (err: unknown) {
+        setResult('');
+      }
+    }, 300);
+
+    return () => {
+      if (debounceTimerRef.current) {
+        clearTimeout(debounceTimerRef.current);
+      }
+    };
+  }, [expression, angleUnit, calcMode]);
