+    if (calcMode === 'rpn') {
+      setStack([res]);
+      setResult(res);
+      setState('evaluated');
+    } else {
+      setExpression(res);
+      setState('evaluated');
+      setResult(res);
+    }
+  };
+
+  const clearHistory = () => {
+    setSessionHistory([]);
+  };
+
+  return {
+    expression,
+    result,
+    history,
+    state,
+    errorMessage,
+    appendToken,
+    clearAll,
+    backspace,
+    evaluateFinal,
+    // Dual Mode & Stack
+    calcMode,
+    toggleCalcMode,
+    stack,
+    // Stage 2 Exports
+    angleUnit,
+    toggleAngleUnit,
+    memory,
+    handleMemoryOperation,
+    clearMemory,
+    recallMemory,
+    sessionHistory,
+    loadHistoryExpression,
+    loadHistoryResult,
+    clearHistory,
+  };
