    const cleanedValue = valueToOperate.replace(/[^\d\.\-eE]/g, '');
    if (!cleanedValue || isNaN(Number(cleanedValue))) return;

    const opSymbol = op === 'add' ? '+' : '-';
    const evaluateExpr = `${memory} ${opSymbol} (${cleanedValue})`;

