  const loadHistoryExpression = (expr: string) => {
    if (calcMode === 'rpn') {
      // For RPN, parse history expression (which is space-separated postfix) into stack
      const tokens = expr.split(' ');
      setStack(tokens);
      if (tokens.length > 0) {
        setResult(tokens[tokens.length - 1]);
      }
      setState('evaluated');
    } else {
      setExpression(expr);
      setState('active');
    }
  };

  const loadHistoryResult = (res: string) => {
    if (calcMode === 'rpn') {
      setStack([res]);
      setResult(res);
      setState('evaluated');
    } else {
      setExpression(res);
      setState('evaluated');
      setResult(res);
    }
  };

  const clearHistory = () => {
    setSessionHistory([]);
  };
...
    errorMessage,
    appendToken,
    clearAll,
    backspace,
    evaluateFinal,
    // Dual Mode & Stack
    calcMode,
    toggleCalcMode,
    stack,
    // Stage 2 Exports
    angleUnit,
    toggleAngleUnit,
