  border: 1px solid rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  outline: none;
  transition: background-color 0.3s ease-in-out;
}

/* Recessed display panel card bezel */
.display-panel {
  background-color: var(--bg-display);
  border-radius: 12px; /* rounded-display */
  padding: 16px; /* padding-inner */
  box-shadow: var(--display-inset-shadow);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  min-height: 120px;
  margin-bottom: 20px; /* display-to-grid */
  text-align: right;
  overflow: hidden;
  transition: background-color 0.3s ease-in-out;
}

/* Stable monospace display numbers formatting */
.display-monospace {
  font-family: "Courier New", "Menlo", "SF Mono", "Consolas", monospace;
  overflow-x: auto;
  white-space: nowrap;
  width: 100%;
  scrollbar-width: none; /* Hide scrollbars */
}

.display-monospace::-webkit-scrollbar {
  display: none;
}

.display-history {
  font-size: 14px; /* size-history */
  color: var(--text-result-preview);
  min-height: 20px;
  margin-bottom: 4px;
}

.display-input {
  font-size: 28px; /* size-display-input */
  color: var(--text-primary);
  font-weight: 500;
  min-height: 36px;
  margin-bottom: 4px;
}

.display-result {
  font-size: 40px; /* size-display-result */
  font-weight: 700;
  min-height: 48px;
  transition: color 0.15s ease-in-out;
}

.display-result.preview {
  color: var(--text-result-preview);
  opacity: 0.7;
}

.display-result.final {
  color: var(--text-result-final);
}

.display-result.error {
  color: var(--text-error);
}

/* 4x5 Button Grid wrapper */
.button-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px; /* grid-gap */
}

/* Standard Tactical interactive button element */
.calc-button {
  aspect-ratio: 1; /* Squarish desktop ratio */
  min-height: 48px; /* Interactive mobile tap target clearance min */
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-size: 20px;
  font-weight: 600;
  border-radius: 8px; /* rounded-button */
  border: var(--border-btn);
  box-shadow: var(--shadow-btn);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: transform 0.1s ease-in-out, background-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
  outline: none;
}

/* Active plunge transforms simulating physical plunger button travel */
.calc-button:active:not(:disabled) {
  transform: scale(0.97);
  box-shadow: none;
}

.calc-button:focus-visible {
  box-shadow: 0px 0px 0px 3px var(--btn-focus-ring);
}

.calc-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Hierarchy Color Styles mapped from DESIGN.md */
.calc-button.operand {
  background-color: var(--btn-operand-bg);
  color: var(--btn-operand-text);
}

.calc-button.operand:hover:not(:disabled) {
  background-color: var(--bg-app);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.operator {
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
}

.calc-button.operator:hover:not(:disabled) {
  filter: brightness(0.95);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.command {
  background-color: var(--btn-command-bg);
  color: var(--btn-command-text);
}

.calc-button.command:hover:not(:disabled) {
  filter: brightness(0.92);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.equals {
  background-color: var(--btn-equals-bg);
  color: var(--btn-equals-text);
}

.calc-button.equals:hover:not(:disabled) {
  filter: brightness(1.1);
  box-shadow: var(--shadow-btn-hover);
}

/* ========================================== */
/* Stage 2 Scientific Extensions & Layouts    */
/* ========================================== */

/* Layout wrapper to place the history drawer next to the calculator on wide screens */
.calculator-layout-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: flex-start;
  gap: 24px;
  width: 100%;
  max-width: 800px; /* Expands to fit both if drawer is open */
  flex-wrap: wrap; /* Collapses drawers below on smaller screens */
}

/* Header Action Toggles Bar */
.calculator-header-toggles {
  display: flex;
  justify-content: space-between;
  width: 100%;
  margin-bottom: 12px;
  gap: 8px;
}

.toggle-btn {
  flex: 1;
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
  border: var(--border-btn);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  outline: none;
  min-height: 38px;
  text-align: center;
}

.toggle-btn:hover {
  filter: brightness(0.95);
}

.toggle-btn.active {
  background-color: var(--text-result-final);
  color: var(--btn-operand-bg);
  border-color: transparent;
}

/* Indicators Row inside Display Panel Bezel */
.display-indicators-row {
  display: flex;
  width: 100%;
  justify-content: flex-end;
  gap: 6px;
  margin-bottom: 8px;
  min-height: 18px;
}

.indicator-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  font-family: "Inter", sans-serif;
  letter-spacing: 0.5px;
}

.angle-badge {
  background-color: var(--btn-command-bg);
  color: var(--btn-command-text);
}

.memory-badge {
  background-color: var(--text-result-final);
  color: #FFFFFF;
  animation: pulse-badge 1.5s infinite alternate;
}

@keyframes pulse-badge {
  from { opacity: 0.8; }
  to { opacity: 1; }
}

.rpn-badge {
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
  margin-left: 6px;
}

.rpn-stack-display {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
  padding-bottom: 6px;
  margin-bottom: 6px;
}

.stack-level {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-result-preview);
  opacity: 0.8;
}

.stack-label {
  font-weight: 700;
  color: var(--btn-operator-text);
  font-family: "Inter", sans-serif;
}

.stack-value {
  text-align: right;
  overflow-x: auto;
  white-space: nowrap;
  scrollbar-width: none;
}
.stack-value::-webkit-scrollbar {
  display: none;
}

/* Keypad Section (Basic and Scientific Side-by-side or Collapsed) */
.keypad-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.scientific-grid {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

@media (prefers-color-scheme: dark) {
  .scientific-grid {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  }
}

/* Side drawer calculation history panel */
.history-drawer-panel {
  width: 100%;
  max-width: 360px;
  min-width: 280px;
  background-color: var(--bg-frame);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0px 8px 32px rgba(0, 0, 0, 0.15);
  border: 1px solid rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  max-height: 600px;
