}

.drawer-header h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.drawer-close-btn {
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: var(--text-result-preview);
  line-height: 1;
}

.drawer-body {
