}

.no-history-msg {
  color: var(--text-result-preview);
  font-size: 14px;
  text-align: center;
  margin-top: 40px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-item-row {
  background-color: var(--bg-display);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: var(--shadow-btn);
}

.history-expr-preview {
  font-family: monospace;
  font-size: 13px;
  color: var(--text-primary);
  word-break: break-all;
  white-space: pre-wrap;
}

.history-res-preview {
  font-family: monospace;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-result-final);
  word-break: break-all;
