/* Stage 2 Scientific Extensions & Layouts    */
/* ========================================== */

/* Layout wrapper to place the history drawer next to the calculator on wide screens */
.calculator-layout-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: flex-start;
  gap: 24px;
  width: 100%;
  max-width: 800px; /* Expands to fit both if drawer is open */
  flex-wrap: wrap; /* Collapses drawers below on smaller screens */
}

/* Header Action Toggles Bar */
.calculator-header-toggles {
  display: flex;
  justify-content: space-between;
  width: 100%;
  margin-bottom: 12px;
  gap: 8px;
}

.toggle-btn {
  flex: 1;
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
  border: var(--border-btn);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  outline: none;
  min-height: 38px;
  text-align: center;
}

.toggle-btn:hover {
  filter: brightness(0.95);
}

.toggle-btn.active {
  background-color: var(--text-result-final);
  color: var(--btn-operand-bg);
  border-color: transparent;
}

/* Indicators Row inside Display Panel Bezel */
.display-indicators-row {
  display: flex;
  width: 100%;
  justify-content: flex-end;
  gap: 6px;
  margin-bottom: 8px;
  min-height: 18px;
}

.indicator-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  font-family: "Inter", sans-serif;
  letter-spacing: 0.5px;
}

.angle-badge {
  background-color: var(--btn-command-bg);
  color: var(--btn-command-text);
}

.memory-badge {
  background-color: var(--text-result-final);
  color: #FFFFFF;
  animation: pulse-badge 1.5s infinite alternate;
}

@keyframes pulse-badge {
  from { opacity: 0.8; }
  to { opacity: 1; }
}

.rpn-badge {
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
  margin-left: 6px;
}

.rpn-stack-display {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
  padding-bottom: 6px;
  margin-bottom: 6px;
}

.stack-level {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-result-preview);
  opacity: 0.8;
}

.stack-label {
  font-weight: 700;
  color: var(--btn-operator-text);
  font-family: "Inter", sans-serif;
}

.stack-value {
  text-align: right;
  overflow-x: auto;
  white-space: nowrap;
  scrollbar-width: none;
}
.stack-value::-webkit-scrollbar {
  display: none;
}

/* Keypad Section (Basic and Scientific Side-by-side or Collapsed) */
.keypad-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.scientific-grid {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

@media (prefers-color-scheme: dark) {
  .scientific-grid {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  }
}

/* Side drawer calculation history panel */
.history-drawer-panel {
  width: 100%;
  max-width: 360px;
  min-width: 280px;
  background-color: var(--bg-frame);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0px 8px 32px rgba(0, 0, 0, 0.15);
  border: 1px solid rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  max-height: 600px;
  transition: background-color 0.3s ease-in-out;
}

.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.drawer-header h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.drawer-close-btn {
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: var(--text-result-preview);
  line-height: 1;
}

.drawer-body {
  flex: 1;
  overflow-y: auto;
  max-height: 400px;
  scrollbar-width: thin;
}

.no-history-msg {
  color: var(--text-result-preview);
  font-size: 14px;
  text-align: center;
  margin-top: 40px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-item-row {
  background-color: var(--bg-display);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: var(--shadow-btn);
}

.history-expr-preview {
  font-family: monospace;
  font-size: 13px;
  color: var(--text-primary);
  word-break: break-all;
  white-space: pre-wrap;
}

.history-res-preview {
  font-family: monospace;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-result-final);
  word-break: break-all;
  white-space: pre-wrap;
}

.history-item-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

.history-item-actions button {
  background-color: var(--btn-operand-bg);
  color: var(--btn-operand-text);
  border: var(--border-btn);
  padding: 4px 8px;
  font-size: 11px;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.1s;
}

.history-item-actions button:hover {
  background-color: var(--btn-command-bg);
}

.drawer-footer {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  display: flex;
  justify-content: center;
}

.clear-history-btn {
  background-color: var(--text-error);
  color: #FFFFFF;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  transition: opacity 0.15s;
}

.clear-history-btn:hover {
  opacity: 0.9;
}

